import{_ as a,o as i,c as e,a2 as t}from"./chunks/framework.BWixA7XM.js";const k=JSON.parse('{"title":"抓取一次转储","description":"","frontmatter":{},"headers":[],"relativePath":"guide/dump/capture.md","filePath":"guide/dump/capture.md","lastUpdated":1795572648000}'),n={name:"guide/dump/capture.md"};function l(p,s,d,r,h,o){return i(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="抓取一次转储" tabindex="-1">抓取一次转储 <a class="header-anchor" href="#抓取一次转储" aria-label="Permalink to &quot;抓取一次转储&quot;">​</a></h1><p>这一节讲怎么让 3DMigoto 在<strong>你想要的时刻</strong>、把<strong>你想要的东西</strong>dump 下来。</p><h2 id="d3dx-ini-里跟提取相关的配置" tabindex="-1"><code>d3dx.ini</code> 里跟提取相关的配置 <a class="header-anchor" href="#d3dx-ini-里跟提取相关的配置" aria-label="Permalink to &quot;\`d3dx.ini\` 里跟提取相关的配置&quot;">​</a></h2><p>3DMigoto 的配置文件叫 <code>d3dx.ini</code>，跟 <code>d3d11.dll</code> 放在一起。跟 FrameAnalysis 有关的段落大致是：</p><div class="language-ini vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">[Logging]</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">calls</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=1</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">dump_calls</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=0</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">dump_include_vertex_buffers</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=1</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">[Hunting]</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">hunting</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=1</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>逐个说：</p><h3 id="calls-1" tabindex="-1"><code>calls=1</code> <a class="header-anchor" href="#calls-1" aria-label="Permalink to &quot;\`calls=1\`&quot;">​</a></h3><p>打开调用日志。<strong>必须开</strong> —— 没有 log，你就无法建立「资源哈希 → 文件」的映射。</p><h3 id="dump-include-vertex-buffers-1" tabindex="-1"><code>dump_include_vertex_buffers=1</code> <a class="header-anchor" href="#dump-include-vertex-buffers-1" aria-label="Permalink to &quot;\`dump_include_vertex_buffers=1\`&quot;">​</a></h3><p>把顶点缓冲也一起 dump。不开的话只有索引和纹理，模型就提取不出来了。</p><h3 id="dump-options-的其它开关" tabindex="-1"><code>dump_options</code> 的其它开关 <a class="header-anchor" href="#dump-options-的其它开关" aria-label="Permalink to &quot;\`dump_options\` 的其它开关&quot;">​</a></h3><p>不同版本写法略有差异，常见的有：</p><table tabindex="0"><thead><tr><th>配置</th><th>作用</th><th>建议</th></tr></thead><tbody><tr><td><code>dump_include_index_buffers</code></td><td>导出索引缓冲</td><td>开</td></tr><tr><td><code>dump_include_vertex_buffers</code></td><td>导出顶点缓冲</td><td>开</td></tr><tr><td><code>dump_include_textures</code></td><td>导出贴图</td><td>开</td></tr><tr><td><code>dump_include_cb_buffers</code></td><td>导出常量缓冲</td><td>开（骨骼矩阵常在）</td></tr><tr><td><code>deduped</code></td><td>去重保存</td><td>见下</td></tr></tbody></table><h3 id="deduped-的取舍" tabindex="-1"><code>deduped</code> 的取舍 <a class="header-anchor" href="#deduped-的取舍" aria-label="Permalink to &quot;\`deduped\` 的取舍&quot;">​</a></h3><p>3Dmigoto 有「内容相同只存一份」的机制。</p><p><strong>开着的好处</strong>：一个大场景里同一个顶点缓冲被 200 个 draw 引用，只存一份，省几百倍空间。</p><p><strong>开着的坏处</strong>：文件名变成内容哈希，你必须解析 log 才能找到真实文件。</p><p><strong>关掉的好处</strong>：文件名就是逻辑名，<code>000038-ib=7ad7e69e-vb0....buf</code> 直接能读，脚本简单很多。</p><p><strong>关掉的坏处</strong>：空间爆掉。一个 8000 draw 的帧可能产生几十 GB。</p><div class="tip custom-block"><p class="custom-block-title">我的建议</p><p><strong>保持 deduped 开着</strong>，在脚本里老实解析 log。</p><p>理由：解析 log 是<strong>一次性的工程成本</strong>（写一个函数，二十行），而关掉 deduped 是<strong>每次抓帧都付出的成本</strong>（几十 GB、拷贝极慢）。而且有些版本的 3Dmigoto 在超大帧下会因为不 dedup 而把磁盘写满，dump 直接失败。</p><p>教程里所有脚本都走 log 解析，你抄过去就能用。</p></div><h2 id="抓帧的时机" tabindex="-1">抓帧的时机 <a class="header-anchor" href="#抓帧的时机" aria-label="Permalink to &quot;抓帧的时机&quot;">​</a></h2><p>3DMigoto 的 FrameAnalysis 通常是按 <strong>F8</strong> 触发。有些版本是 F8 抓一帧，有些是 F8 开始连续抓、再按一次停止。</p><p>抓帧的关键是<strong>让想要的模型出现在画面里</strong>：</p><ul><li>想要角色的身体 → 转到能看到正脸的角度，确保角色完全在视野内</li><li>想要某个武器 → 让它别被手挡住</li><li>想要某个 UI 元素 → 保证它在屏幕上显示</li></ul><div class="warning custom-block"><p class="custom-block-title">视角会影响结果</p><p>模型被视锥体裁掉（不在视野里）就<strong>不会被绘制</strong>，也就不会出现在转储里。</p><p>同样，如果角色被别的物体遮挡，后面的部分可能被裁掉。抓帧时转一转视角，确保目标完整可见。</p></div><h2 id="抓多次、抓不同场景" tabindex="-1">抓多次、抓不同场景 <a class="header-anchor" href="#抓多次、抓不同场景" aria-label="Permalink to &quot;抓多次、抓不同场景&quot;">​</a></h2><p>单次转储只能看到那一帧被画的东西。想拿到完整信息，可能需要抓两三次：</p><table tabindex="0"><thead><tr><th>场景</th><th>抓什么</th></tr></thead><tbody><tr><td>角色静止站立</td><td>拿到标准姿势、完整贴图</td></tr><tr><td>角色做动作</td><td>对比姿势，确认哪份是 T-pose</td></tr><tr><td>换一套服装</td><td>拿到多套贴图、多个 IB</td></tr></tbody></table><h2 id="抓到之后先别急着开工" tabindex="-1">抓到之后先别急着开工 <a class="header-anchor" href="#抓到之后先别急着开工" aria-label="Permalink to &quot;抓到之后先别急着开工&quot;">​</a></h2><p>打开目录看几件事，能提前避掉很多坑：</p><h3 id="_1-确认-log-txt-存在且不小" tabindex="-1">1. 确认 <code>log.txt</code> 存在且不小 <a class="header-anchor" href="#_1-确认-log-txt-存在且不小" aria-label="Permalink to &quot;1. 确认 \`log.txt\` 存在且不小&quot;">​</a></h3><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ls</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -lh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> log.txt</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>几 MB 是正常。几 KB 说明 <code>calls=1</code> 没开，这个转储废了，要重新抓。</p><h3 id="_2-数一下-ib-有多少个" tabindex="-1">2. 数一下 IB 有多少个 <a class="header-anchor" href="#_2-数一下-ib-有多少个" aria-label="Permalink to &quot;2. 数一下 IB 有多少个&quot;">​</a></h3><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 平铺形态</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ls</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> *</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ib=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">*</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.txt</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> wc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -l</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># deduped 形态（真实文件在 deduped 里）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ls</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deduped/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">*</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">topology</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">*</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.txt</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> wc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -l</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>几十到几百个都正常。太多（几千）说明这一帧画的东西特别多，找目标 IB 会累一点。</p><h3 id="_3-看-topology-分布" tabindex="-1">3. 看 topology 分布 <a class="header-anchor" href="#_3-看-topology-分布" aria-label="Permalink to &quot;3. 看 topology 分布&quot;">​</a></h3><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 哪些是三角形，哪些是点</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ls</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deduped/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">*</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">topology=trianglelist</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">*</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> wc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -l</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ls</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deduped/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">*</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">topology=pointlist</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">*</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">     |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> wc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -l</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><div class="tip custom-block"><p class="custom-block-title">这个小检查有大用处</p><p><code>pointlist</code> 的文件数量通常很少（几十个以内），但它们<strong>极其重要</strong> —— GPU 预蒙皮的 T-pose 顶点和骨骼权重就藏在这里。</p><p>如果 <code>pointlist</code> 数量是 0，你这个转储里<strong>没有</strong> GPU 预蒙皮数据，模型只能拿到已蒙皮的姿势。见<a href="/SSMT4-Tutorial/guide/gametype/preskinning">GPU 与 CPU 预蒙皮</a>。</p></div><h3 id="_4-确认-deduped-里的文件类型分布" tabindex="-1">4. 确认 deduped 里的文件类型分布 <a class="header-anchor" href="#_4-确认-deduped-里的文件类型分布" aria-label="Permalink to &quot;4. 确认 deduped 里的文件类型分布&quot;">​</a></h3><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ls</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deduped/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sed</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;s/.*\\.//&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sort</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> uniq</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>典型输出：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>    243 buf</span></span>
<span class="line"><span>    446 txt</span></span>
<span class="line"><span>    285 dds</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>如果 <code>.buf</code> 数量是 0，说明 <code>dump_include_vertex_buffers</code> 没开 —— 这个转储只有描述没有数据，废了。</p><h2 id="存储与清理" tabindex="-1">存储与清理 <a class="header-anchor" href="#存储与清理" aria-label="Permalink to &quot;存储与清理&quot;">​</a></h2><p>一次完整转储轻松上 1 GB。抓几次就几个 GB。</p><p>建议：</p><ul><li>抓到有用的转储，<strong>立刻归档</strong>到一个专门的目录，重命名成有意义的名字（<code>FFA-20261117-角色A站立</code>）</li><li>不要的转储<strong>及时删掉</strong>，不要攒</li><li>转储目录<strong>只读对待</strong>，所有产物写到别的目录 —— 避免脚本一不小心改坏原始数据</li></ul><div class="danger custom-block"><p class="custom-block-title">不要修改转储目录</p><p>转储是唯一的事实来源。一旦被脚本改坏（比如误写了某个 <code>.buf</code>），你就得重新抓帧。</p><p>脚本里所有输出路径都指向工作目录，不要指向 dump 目录。</p></div><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p>→ <a href="/SSMT4-Tutorial/guide/dump/find-ib">锁定目标 IB</a>：从几百个 IB 里找出你要的那个</p>`,51)])])}const u=a(n,[["render",l]]);export{k as __pageData,u as default};
